package com.bank.plandiag.plan;

public class PlanNode {
    private final String nodeType;      // Seq Scan, Index Scan, Nested Loop, Hash Join, Sort
    private final boolean indexExpected; // did we expect an index here?
    private final boolean sargable;
    private final long estRows;
    private final long actualRows;

    public PlanNode(String nodeType, boolean indexExpected, boolean sargable, long estRows, long actualRows) {
        this.nodeType = nodeType; this.indexExpected = indexExpected;
        this.sargable = sargable; this.estRows = estRows; this.actualRows = actualRows;
    }
    public String getNodeType() { return nodeType; }
    public boolean isIndexExpected() { return indexExpected; }
    public boolean isSargable() { return sargable; }
    public long getEstRows() { return estRows; }
    public long getActualRows() { return actualRows; }
}
