package com.bank.plandiag.service;

import com.bank.plandiag.plan.PlanNode;
import java.util.*;
import java.util.logging.*;

public class PlanDiagnostician {
    private static final Logger log = Logger.getLogger(PlanDiagnostician.class.getName());
    private final long bigOuterThreshold;
    private final long staleRatio;

    public PlanDiagnostician(long bigOuterThreshold, long staleRatio) {
        this.bigOuterThreshold = bigOuterThreshold; this.staleRatio = staleRatio;
    }

    public List<String> diagnose(List<PlanNode> plan) {
        List<String> findings = new ArrayList<>();
        for (PlanNode n : plan) {
            // Signature 1: Seq Scan where an index was expected
            if (n.getNodeType().equals("Seq Scan") && n.isIndexExpected()) {
                String cause = n.isSargable() ? "missing index or low selectivity" : "non-sargable predicate (function on column)";
                findings.add("Seq Scan where Index expected → " + cause + " → add index / rewrite predicate");
            }
            // Signature 2: Nested Loop with huge outer
            if (n.getNodeType().equals("Nested Loop") && n.getActualRows() > bigOuterThreshold) {
                findings.add("Nested Loop outer=" + n.getActualRows() + " (huge) → switch to Hash Join");
            }
            // Signature 3: costly Sort
            if (n.getNodeType().equals("Sort")) {
                findings.add("Costly Sort → add index on ORDER BY columns to avoid the sort");
            }
            // Signature 4: stale statistics (estimate vs actual gap)
            if (n.getEstRows() > 0 && n.getActualRows() > n.getEstRows() * staleRatio) {
                findings.add("Estimate " + n.getEstRows() + " vs actual " + n.getActualRows()
                        + " → stale statistics → ANALYZE the table");
            }
        }
        findings.forEach(f -> log.warning(() -> "DIAGNOSIS: " + f));
        if (findings.isEmpty()) log.info("Plan looks healthy");
        return findings;
    }
}
