package com.bank.plandiag;

import com.bank.plandiag.plan.PlanNode;
import com.bank.plandiag.service.PlanDiagnostician;
import java.util.*;
import java.util.logging.*;

public class PlanDiagDemo {
    private static final Logger log = Logger.getLogger(PlanDiagDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        PlanDiagnostician doc = new PlanDiagnostician(1_000_000L, 100L);

        List<PlanNode> problemPlan = List.of(
            // Seq Scan where index expected, non-sargable predicate
            new PlanNode("Seq Scan", true, false, 500, 500),
            // Nested Loop with huge outer table
            new PlanNode("Nested Loop", false, true, 5_000_000, 5_000_000),
            // costly Sort on created_at
            new PlanNode("Sort", false, true, 5_000_000, 5_000_000),
            // stale statistics: estimated 10, actual 5,000,000
            new PlanNode("Index Scan", false, true, 10, 5_000_000)
        );

        log.info("Diagnosing slow report plan...");
        doc.diagnose(problemPlan);
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

